function fromProjectSource_kind(o: w.ProjectSource["kind"]): Part<p.ProjectSource, "kind" | "files" | "github"> {
  switch (o.case) {
    case "files": return { kind: "files", files: o.value };
    case "github": return { kind: "github", github: fromGithubSource(o.value) };
    case undefined: return {};
    default: o satisfies never; return {};
  }
}

export function toProjectSource(m: p.ProjectSourceInput): MessageInitShape<typeof w.ProjectSourceSchema> {
  return {
    kind: toProjectSource_kind(m),
  } satisfies Fields<w.ProjectSource>;
}

function toProjectSource_kind(m: p.ProjectSourceInput): MessageInitShape<typeof w.ProjectSourceSchema>["kind"] {
  written<Unwritten<MessageInitShape<typeof w.ProjectSourceSchema>["kind"], "files" | "github">>();
  const set: NonNullable<MessageInitShape<typeof w.ProjectSourceSchema>["kind"]>[] = [];
  if (m.files !== undefined) set.push({ case: "files", value: m.files });
  if (m.github !== undefined) set.push({ case: "github", value: toGithubSource(m.github) });
  return only("kind", set);
}

